    public function actionAuth()
    {
        $app = new DropboxApp("REDACTED_BEFORE_PUBLICATION", "REDACTED_BEFORE_PUBLICATION");
        $dropbox = new Dropbox($app);
        $authHelper = $dropbox->getAuthHelper();
        $callbackUrl = "https://www.madwave.ru/dropbox/auth-callback";
        return $this->redirect($authHelper->getAuthUrl($callbackUrl));
    }

    private function getNotification()
    {
        $signature = null;

        if (isset($_SERVER['HTTP_X_DROPBOX_SIGNATURE'])) {
            $signature = $_SERVER['HTTP_X_DROPBOX_SIGNATURE'];
        }

        if (empty($signature)) {
            throw new BadRequestHttpException('HTTP_X_DROPBOX_SIGNATURE must be provided from dropbox');
        }

        $httpbody = file_get_contents('php://input');

        $hmac = hash_hmac( 'sha256', $httpbody, $this->secret );

        if ($signature !== $hmac) {
            throw new BadRequestHttpException('HTTP_X_DROPBOX_SIGNATURE is wrong');
        }

        return $httpbody;
    }
